"Lychee Puree","quantity":45,"sizes":{"Medium 16oz":1,"Large 22oz":1.4}}]},{"id":"e5000000-0000-4000-a000-000000000005","name":"Honey Peach Soda","category":"Refreshers","icedOnly":true,"portions":[{"ingredient":"Soda Water","quantity":250,"sizes":{"Medium 16oz":1,"Large 22oz":1.4}},{"ingredient":"Ice","quantity":150,"sizes":{"Medium 16oz":1,"Large 22oz":1.4}},{"ingredient":"Honey Peach Puree","quantity":45,"sizes":{"Medium 16oz":1,"Large 22oz":1.4}}]},{"id":"e6000000-0000-4000-a000-000000000001","name":"Just Croffle","category":"Croffles","icedOnly":false,"portions":[{"ingredient":"Croffle Dough","quantity":1,"sizes":{}},{"ingredient":"Powdered Sugar","quantity":5,"sizes":{}}]},{"id":"e6000000-0000-4000-a000-000000000002","name":"S''mores","category":"Croffles","icedOnly":false,"portions":[{"ingredient":"Croffle Dough","quantity":1,"sizes":{}},{"ingredient":"Marshmallows","quantity":20,"sizes":{}},{"ingredient":"Chocolate Chips","quantity":15,"sizes":{}}]},{"id":"e6000000-0000-4000-a000-000000000003","name":"Banatella","category":"Croffles","icedOnly":false,"portions":[{"ingredient":"Croffle Dough","quantity":1,"sizes":{}},{"ingredient":"Banana","quantity":0.5,"sizes":{}},{"ingredient":"Nutella","quantity":20,"sizes":{}}]},{"id":"e6000000-0000-4000-a000-000000000004","name":"Biscoff Croffle","category":"Croffles","icedOnly":false,"portions":[{"ingredient":"Croffle Dough","quantity":1,"sizes":{}},{"ingredient":"Biscoff Spread","quantity":20,"sizes":{}}]},{"id":"e6000000-0000-4000-a000-000000000005","name":"Almond Nutella","category":"Croffles","icedOnly":false,"portions":[{"ingredient":"Croffle Dough","quantity":1,"sizes":{}},{"ingredient":"Nutella","quantity":20,"sizes":{}},{"ingredient":"Almonds (sliced)","quantity":10,"sizes":{}}]},{"id":"e6000000-0000-4000-a000-000000000006","name":"Ham & Cheese","category":"Croffles","icedOnly":false,"portions":[{"ingredient":"Croffle Dough","quantity":1,"sizes":{}},{"ingredient":"Ham Slice","quantity":2,"sizes":{}},{"ingredient":"Cheese Slice","quantity":1,"sizes":{}}]},{"id":"e7000000-0000-4000-a000-000000000001","name":"Flavored Fries","category":"Snacks","icedOnly":false,"portions":[{"ingredient":"French Fries (frozen)","quantity":150,"sizes":{}},{"ingredient":"Frying Oil","quantity":15,"sizes":{}}]},{"id":"e7000000-0000-4000-a000-000000000002","name":"Nachos","category":"Snacks","icedOnly":false,"portions":[{"ingredient":"Tortilla Chips","quantity":90,"sizes":{}},{"ingredient":"Nacho Cheese Sauce","quantity":40,"sizes":{}}]},{"id":"e7000000-0000-4000-a000-000000000003","name":"Chicken Pop","category":"Snacks","icedOnly":false,"portions":[{"ingredient":"Chicken Poppers (frozen)","quantity":150,"sizes":{}},{"ingredient":"Frying Oil","quantity":15,"sizes":{}}]}]'::jsonb) LOOP
  IF NOT EXISTS(SELECT 1 FROM menu_items WHERE id=(product->>'id')::uuid AND name=product->>'name') THEN CONTINUE; END IF;
  DELETE FROM menu_item_ingredients WHERE menu_item_id=(product->>'id')::uuid;
  FOR portion IN SELECT value FROM jsonb_array_elements(product->'portions') LOOP
   SELECT id INTO ingredient FROM ingredients WHERE name=portion->>'ingredient';
   IF ingredient IS NULL THEN RAISE EXCEPTION 'Missing recipe ingredient: %',portion->>'ingredient'; END IF;
   INSERT INTO menu_item_ingredients(menu_item_id,ingredient_id,quantity_used,size_multipliers)
   VALUES((product->>'id')::uuid,ingredient,(portion->>'quantity')::numeric,portion->'sizes');
  END LOOP;
  IF product->>'category'='Refreshers' AND NOT EXISTS(SELECT 1 FROM item_variants WHERE menu_item_id=(product->>'id')::uuid AND variant_group='size') THEN
   INSERT INTO item_variants(menu_item_id,variant_group,label,price_modifier,is_default,sort_order) VALUES((product->>'id')::uuid,'size','Medium 16oz',0,true,0);
  END IF;
  IF (product->>'icedOnly')::boolean THEN
   DELETE FROM item_variants WHERE menu_item_id=(product->>'id')::uuid AND variant_group='temperature' AND label='Hot';
   DELETE FROM item_variants WHERE menu_item_id=(product->>'id')::uuid AND variant_group='size' AND label='Hot 12oz';
  END IF;
 END LOOP;
END $recipes$;
-- The size mappings supply exactly one cup/lid/straw. Hot drinks use the existing hot lid stock.
INSERT INTO variant_ingredients(variant_group,variant_label,ingredient_id,quantity_used)
SELECT 'size','Hot 12oz',i.id,1 FROM ingredients i WHERE i.name='Lid'
AND NOT EXISTS(SELECT 1 FROM variant_ingredients v WHERE v.variant_group='size' AND v.variant_label='Hot 12oz' AND v.ingredient_id=i.id);
-- Flavored fries must actually consume the selected seasoning.
INSERT INTO variant_ingredients(variant_group,variant_label,ingredient_id,quantity_used)
SELECT 'flavor',x.label,i.id,5 FROM (VALUES ('Cheese','Cheese Seasoning'),('Sour Cream','Sour Cream Seasoning'),('BBQ','BBQ Seasoning')) x(label,ingredient)
JOIN ingredients i ON i.name=x.ingredient WHERE NOT EXISTS(SELECT 1 FROM variant_ingredients v WHERE v.variant_group='flavor' AND v.variant_label=x.label AND v.ingredient_id=i.id);
-- Dry pearls are measured before cooking. Melted chocolate chips supply the drizzle.
UPDATE variant_ingredients SET quantity_used=20 WHERE variant_group='add_on' AND variant_label='Tapioca Pearls' AND ingredient_id IN(SELECT id FROM ingredients WHERE name='Tapioca Pearls (raw)');
UPDATE variant_ingredients SET ingredient_id=(SELECT id FROM ingredients WHERE name='Chocolate Chips') WHERE variant_group='add_on' AND variant_label='Chocolate Drizzle' AND ingredient_id IN(SELECT id FROM ingredients WHERE name='Chocolate Powder') AND EXISTS(SELECT 1 FROM ingredients WHERE name='Chocolate Chips');

CREATE OR REPLACE FUNCTION public.inv_requirements(p_item uuid,p_variants jsonb DEFAULT '[]',p_quantity numeric DEFAULT 1)
RETURNS TABLE(ingredient_id uuid,quantity numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH size AS(SELECT COALESCE((SELECT v->>'label' FROM jsonb_array_elements(p_variants) v WHERE v->>'variant_group'='size' LIMIT 1),'Medium 16oz') label),
config AS(SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE (v->>'variant_group'='temperature' AND v->>'label'='Hot') OR (v->>'variant_group'='size' AND v->>'label'='Hot 12oz')) hot,
 EXISTS(SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE v->>'variant_group'='sugar_level' AND v->>'label'='Less Sweet') less_sweet),
selected AS(SELECT vi.* FROM variant_ingredients vi WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE v->>'label'=vi.variant_label AND v->>'variant_group'=vi.variant_group)),
base AS(SELECT m.ingredient_id,m.quantity_used*COALESCE((m.size_multipliers->>(SELECT label FROM size))::numeric,1) qty FROM menu_item_ingredients m
 WHERE m.menu_item_id=p_item AND NOT EXISTS(SELECT 1 FROM selected s WHERE s.replaces_ingredient_id=m.ingredient_id)),
extra AS(SELECT s.ingredient_id,s.quantity_used*COALESCE((s.size_multipliers->>(SELECT label FROM size))::numeric,
 (SELECT (r.size_multipliers->>(SELECT label FROM size))::numeric FROM menu_item_ingredients r WHERE r.menu_item_id=p_item AND r.ingredient_id=s.replaces_ingredient_id),1) qty FROM selected s
 WHERE NOT EXISTS(SELECT 1 FROM selected replacement WHERE replacement.replaces_ingredient_id=s.ingredient_id AND replacement.id<>s.id)),
combined AS(SELECT * FROM base UNION ALL SELECT * FROM extra)
SELECT c.ingredient_id,sum(c.qty*CASE WHEN config.less_sweet AND i.name IN ('Vanilla Syrup','French Vanilla Syrup','Caramel Syrup','Hazelnut Syrup','Macadamia Syrup','Butterscotch Syrup','White Mocha Sauce','Salted Caramel Sauce','Condensed Milk','Brown Sugar Syrup','Simple Syrup') THEN 0.5 ELSE 1 END)*p_quantity
FROM combined c JOIN ingredients i ON i.id=c.ingredient_id CROSS JOIN config
WHERE NOT(config.hot AND i.name='Ice') GROUP BY c.ingredient_id HAVING sum(c.qty)>0;
$$;

-- Prune impossible configurations before optional-choice enumeration.
CREATE OR REPLACE FUNCTION public.inv_any_configuration_available(p_item uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE config jsonb; defaults jsonb;
BEGIN

 -- A missing mandatory base ingredient cannot be repaired by enumerating options.
 -- Use the smallest configured size, and skip ingredients any option can replace.
 IF EXISTS(SELECT 1 FROM menu_items m WHERE m.id=p_item AND (m.status<>'active' OR NOT m.manually_available)) THEN RETURN false; END IF;
 IF (SELECT enforcement_enabled FROM inventory_settings WHERE id) AND EXISTS(
  SELECT 1 FROM menu_item_ingredients r JOIN ingredients i ON i.id=r.ingredient_id
  WHERE r.menu_item_id=p_item
  AND NOT (i.name='Ice' AND EXISTS(SELECT 1 FROM item_variants iv WHERE iv.menu_item_id=p_item AND ((iv.variant_group='size' AND iv.label='Hot 12oz') OR (iv.variant_group='temperature' AND iv.label='Hot'))))
  AND NOT EXISTS(SELECT 1 FROM variant_ingredients vi JOIN item_variants iv ON iv.menu_item_id=p_item AND iv.variant_group=vi.variant_group AND iv.label=vi.variant_label WHERE vi.replaces_ingredient_id=r.ingredient_id)
  AND (NOT i.is_active OR COALESCE((SELECT sum(GREATEST(0,b.quantity-b.reserved)) FROM stock_batches b WHERE b.ingredient_id=r.ingredient_id AND (b.expires_on IS NULL OR b.expires_on>=inv_business_date())),0)
   <r.quantity_used*CASE WHEN i.name IN ('Vanilla Syrup','French Vanilla Syrup','Caramel Syrup','Hazelnut Syrup','Macadamia Syrup','Butterscotch Syrup','White Mocha Sauce','Salted Caramel Sauce','Condensed Milk','Brown Sugar Syrup','Simple Syrup') AND EXISTS(SELECT 1 FROM item_variants iv WHERE iv.menu_item_id=p_item AND iv.variant_group='sugar_level' AND iv.label='Less Sweet') THEN 0.5 ELSE 1 END*COALESCE((SELECT min(COALESCE((r.size_multipliers->>v.label)::numeric,1)) FROM item_variants v WHERE v.menu_item_id=p_item AND v.variant_group='size'),1))
 ) THEN RETURN false; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('variant_group',variant_group,'label',label)),'[]') INTO defaults FROM item_variants WHERE menu_item_id=p_item AND is_default;
 IF (NOT EXISTS(SELECT 1 FROM item_variants WHERE menu_item_id=p_item AND variant_group='size') OR EXISTS(SELECT 1 FROM jsonb_array_elements(defaults) x WHERE x->>'variant_group'='size')) AND (get_item_availability(p_item,defaults)->>'available')::boolean THEN RETURN true; END IF;
 -- Try optional substitutions as well as sizes when the default recipe is sold out.
 FOR config IN WITH RECURSIVE groups AS (
   SELECT variant_group,row_number() OVER(ORDER BY variant_group)::integer n FROM item_variants WHERE menu_item_id=p_item GROUP BY variant_group
 ), choices(n,config) AS (
   SELECT 0,'[]'::jsonb
   UNION ALL SELECT g.n,c.config||v.choice FROM choices c JOIN groups g ON g.n=c.n+1 CROSS JOIN LATERAL (
     SELECT jsonb_build_array(jsonb_build_object('variant_group',iv.variant_group,'label',iv.label)) choice FROM item_variants iv WHERE iv.menu_item_id=p_item AND iv.variant_group=g.variant_group
     UNION ALL SELECT '[]'::jsonb WHERE g.variant_group='add_on'
   ) v
 ) SELECT c.config FROM choices c WHERE c.n=(SELECT count(*) FROM groups) LOOP
   IF (get_item_availability(p_item,config)->>'available')::boolean THEN RETURN true; END IF;
 END LOOP;
 RETURN false;
END $$;
